import { Collapsible, CollapsiblePanel, CollapsibleTrigger } from '@gntik-ai/ui';
import { toJson } from '../utils/format';
import { toolCallCardStyles } from './toolCallCard.variants';

const s = toolCallCardStyles.json;

export interface JsonViewProps {
  /** Section title ("Arguments", "Result"). */
  label: string;
  /** Any value: objects are pretty-printed, strings shown as-is. */
  value: unknown;
  defaultOpen?: boolean;
}

/** A small collapsible, scrollable JSON block. */
export function JsonView({ label, value, defaultOpen = true }: JsonViewProps) {
  return (
    <Collapsible defaultOpen={defaultOpen}>
      <CollapsibleTrigger className={s.trigger}>{label}</CollapsibleTrigger>
      <CollapsiblePanel className={s.content}>
        <pre tabIndex={0} aria-label={label} className={s.pre}>
          <code>{toJson(value)}</code>
        </pre>
      </CollapsiblePanel>
    </Collapsible>
  );
}

import { Button, Input } from '@gntik-ai/ui';
import { useEffect, useId, useRef, useState } from 'react';
import { useChatI18n } from '../utils/i18n';
import type { ToolCallCardProps } from './ToolCallCard';
import { toolCallCardStyles as s } from './toolCallCard.variants';

type Props = Pick<
  ToolCallCardProps,
  'name' | 'onApprove' | 'onDeny' | 'askDenyReason' | 'destructive' | 'approveLabel' | 'denyLabel' | 'approvalPrompt'
>;

/** Decision controls stay outside the disclosure so collapsing never hides them. */
export function ToolCallApproval({
  name,
  onApprove,
  onDeny,
  askDenyReason = true,
  destructive = false,
  approveLabel,
  denyLabel,
  approvalPrompt,
}: Props) {
  const { t, tc } = useChatI18n();
  const id = useId();
  const approveText =
    approveLabel ?? (destructive ? tc('toolCall.approveDestructive', { name }) : tc('toolCall.approve'));
  const denyText = denyLabel ?? tc('toolCall.deny');
  const [reasonStep, setReasonStep] = useState(false);
  const [reason, setReason] = useState('');
  const input = useRef<HTMLInputElement>(null);
  const denyButton = useRef<HTMLButtonElement>(null);
  const restoreFocus = useRef(false);
  useEffect(() => {
    if (reasonStep) input.current?.focus();
    else if (restoreFocus.current) {
      denyButton.current?.focus();
      restoreFocus.current = false;
    }
  }, [reasonStep]);
  const inFlight = useRef(false);
  const [busy, setBusy] = useState<'approve' | 'deny' | null>(null);

  const run = async (action: 'approve' | 'deny', handler?: () => void | Promise<void>) => {
    if (inFlight.current || !handler) return;
    inFlight.current = true;
    try {
      const result = handler();
      if (result && typeof result.then === 'function') {
        setBusy(action);
      }
      // Keep the guard through this event batch even when the callback returns void.
      await result;
    } catch {
      // The caller reports callback errors; keep the controls available for a retry.
    } finally {
      inFlight.current = false;
      setBusy(null);
    }
  };

  const cancel = () => {
    if (inFlight.current) return;
    restoreFocus.current = true;
    setReasonStep(false);
    setReason('');
  };
  const submitReason = () => void run('deny', onDeny ? () => onDeny(reason.trim() || undefined) : undefined);

  return (
    <div
      role="group"
      aria-labelledby={`${id}-prompt`}
      aria-describedby={destructive ? `${id}-hint` : undefined}
      className={s.approval}
      onKeyDown={(event) => {
        if (reasonStep && event.key === 'Escape') {
          event.preventDefault();
          event.stopPropagation();
          cancel();
        }
      }}
    >
      <p id={`${id}-prompt`} className={s.prompt}>
        {approvalPrompt ?? tc('toolCall.approvalPrompt')}
      </p>
      {destructive && (
        <p id={`${id}-hint`} className={s.hint}>
          {tc('toolCall.destructiveHint')}
        </p>
      )}
      {reasonStep ? (
        <>
          <Input
            ref={input}
            aria-label={tc('toolCall.denyReason')}
            placeholder={tc('toolCall.denyReason')}
            value={reason}
            onValueChange={setReason}
            readOnly={busy !== null}
            onKeyDown={(event) => {
              if (event.key === 'Enter' && !event.nativeEvent.isComposing) {
                event.preventDefault();
                event.stopPropagation();
                submitReason();
              }
            }}
          />
          <Button
            size="sm"
            variant="secondary"
            loading={busy === 'deny'}
            disabled={busy !== null}
            focusableWhenDisabled
            onClick={submitReason}
          >
            {denyText}
          </Button>
          <Button size="sm" variant="secondary" disabled={busy !== null} focusableWhenDisabled onClick={cancel}>
            {t('common.cancel')}
          </Button>
        </>
      ) : (
        <>
          <Button
            size="sm"
            variant={destructive ? 'destructive' : 'primary'}
            loading={busy === 'approve'}
            disabled={busy !== null}
            focusableWhenDisabled
            onClick={() => void run('approve', onApprove)}
          >
            {approveText}
          </Button>
          <Button
            ref={denyButton}
            size="sm"
            variant="secondary"
            loading={busy === 'deny'}
            disabled={busy !== null}
            focusableWhenDisabled
            onClick={() => {
              if (inFlight.current) return;
              if (askDenyReason) setReasonStep(true);
              else void run('deny', onDeny);
            }}
          >
            {denyText}
          </Button>
        </>
      )}
    </div>
  );
}

import { Collapsible, CollapsiblePanel, CollapsibleTrigger, Spinner, StatusTag, cn } from '@gntik-ai/ui';
import { Ban, CircleAlert, Hand, Wrench } from 'lucide-react';
import { useState, type ReactNode, type Ref } from 'react';
import { useChatI18n, type ChatMessageKey } from '../utils/i18n';
import { formatDuration } from '../utils/format';
import { JsonView } from './JsonView';
import { ToolCallApproval } from './ToolCallApproval';
import { toolCallCardStyles as s } from './toolCallCard.variants';

export type ToolCallStatus = 'awaiting-approval' | 'running' | 'succeeded' | 'failed' | 'denied';

export interface ToolCallDecision {
  outcome: 'approved' | 'denied';
  reason?: string;
}

export interface ToolCallCardProps {
  /** Tool / function name, e.g. "search_invoices". */
  name: string;
  status: ToolCallStatus;
  /** Elapsed time in ms. */
  durationMs?: number;
  /** Arguments the model passed. */
  args?: unknown;
  /** What the tool returned. */
  result?: unknown;
  /** Error message for a failed call. */
  error?: string;
  /** Start expanded. Failed, denied and awaiting-approval calls open by default. */
  defaultOpen?: boolean;
  /** Controlled open state. */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Report the decision; the caller controls status and handles errors. */
  onApprove?: () => void | Promise<void>;
  onDeny?: (reason?: string) => void | Promise<void>;
  /** Ask for an optional denial reason. Default true. */
  askDenyReason?: boolean;
  /** Use destructive tone and explicit Run {name} wording. */
  destructive?: boolean;
  approveLabel?: string;
  denyLabel?: string;
  /** Accessible name and visible prompt for the decision group. */
  approvalPrompt?: ReactNode;
  /** Decision supplied by the caller; this card never updates it. */
  decision?: ToolCallDecision;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

const VERB: Record<ToolCallStatus, ChatMessageKey> = {
  'awaiting-approval': 'toolCall.awaitingApproval',
  denied: 'toolCall.denied',
  running: 'toolCall.calling',
  succeeded: 'toolCall.called',
  failed: 'toolCall.failed',
};

/**
 * A tool invocation inside an assistant turn: name, status, duration, and a collapsible body
 * with the arguments and the result (or error) as small JSON views.
 */
export function ToolCallCard({
  name,
  status,
  durationMs,
  args,
  result,
  error,
  defaultOpen,
  open,
  onOpenChange,
  onApprove,
  onDeny,
  askDenyReason,
  destructive,
  approveLabel,
  denyLabel,
  approvalPrompt,
  decision,
  className,
  ref,
}: ToolCallCardProps) {
  const { t, tc } = useChatI18n();
  const awaiting = status === 'awaiting-approval';
  const [expanded, setExpanded] = useState(awaiting || (defaultOpen ?? (status === 'failed' || status === 'denied')));
  const [previousStatus, setPreviousStatus] = useState(status);
  const [announcement, setAnnouncement] = useState(awaiting ? tc('toolCall.approvalRequested', { name }) : '');
  if (previousStatus !== status) {
    setPreviousStatus(status);
    if (awaiting) {
      setExpanded(true);
      setAnnouncement(tc('toolCall.approvalRequested', { name }));
    } else {
      setAnnouncement('');
    }
  }
  const failed = status === 'failed';
  return (
    <Collapsible
      ref={ref}
      open={open ?? expanded}
      onOpenChange={(next) => {
        setExpanded(next);
        onOpenChange?.(next);
      }}
      data-status={status}
      className={cn(s.root, className)}
    >
      <CollapsibleTrigger className={s.trigger}>
        <span
          className={cn(
            s.icon,
            failed && s.iconFailed,
            awaiting && s.iconAwaiting,
            status === 'denied' && s.iconDenied,
          )}
        >
          {status === 'running' ? (
            <Spinner size={13} />
          ) : awaiting ? (
            <Hand size={13} aria-hidden />
          ) : status === 'denied' ? (
            <Ban size={13} aria-hidden />
          ) : failed ? (
            <CircleAlert size={13} aria-hidden />
          ) : (
            <Wrench size={13} aria-hidden />
          )}
        </span>
        <span className={s.label}>
          <span className={s.verb}>{tc(VERB[status])}</span>
          {(awaiting || status === 'denied') && ' '}
          <span className={s.name}>{name}</span>
        </span>
        <span className={s.meta}>
          {durationMs !== undefined && <span className={s.duration}>{formatDuration(durationMs)}</span>}
          <StatusTag
            status={status}
            size="sm"
            statuses={{
              'awaiting-approval': { label: tc('toolCall.statusAwaitingApproval'), tone: 'warning' },
              denied: { label: tc('toolCall.statusDenied'), tone: 'neutral' },
            }}
          />
        </span>
      </CollapsibleTrigger>
      <CollapsiblePanel className="pt-0">
        <div className={s.body}>
          {args !== undefined && <JsonView label={t('toolCall.arguments')} value={args} />}
          {failed && error && (
            <p role="alert" className={s.error}>
              {error}
            </p>
          )}
          {decision && (
            <p className={s.decision}>
              {decision.outcome === 'approved'
                ? tc('toolCall.approved')
                : decision.reason
                  ? tc('toolCall.deniedReason', { reason: decision.reason })
                  : tc('toolCall.statusDenied')}
            </p>
          )}
          {result !== undefined && <JsonView label={t('toolCall.result')} value={result} />}
          {status === 'running' && result === undefined && (
            <p className="text-[12.5px] text-muted-foreground">{t('toolCall.waiting')}</p>
          )}
        </div>
      </CollapsiblePanel>
      {awaiting && (
        <ToolCallApproval
          onApprove={onApprove}
          onDeny={onDeny}
          askDenyReason={askDenyReason}
          name={name}
          destructive={destructive}
          approveLabel={approveLabel}
          denyLabel={denyLabel}
          approvalPrompt={approvalPrompt}
        />
      )}
      {awaiting && (
        <span role="status" aria-live="polite" className="sr-only">
          {announcement}
        </span>
      )}
    </Collapsible>
  );
}

export { ToolCallCard, type ToolCallCardProps, type ToolCallDecision, type ToolCallStatus } from './ToolCallCard';
export { JsonView, type JsonViewProps } from './JsonView';
export { toolCallCardStyles } from './toolCallCard.variants';
export { doc as toolCallCardDoc } from './ToolCallCard.doc';

/** "840 ms" below a second, "2.4 s" below a minute, "1 m 05 s" above. */
export function formatDuration(ms: number) {
  if (ms < 1000) return `${Math.round(ms)} ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)} s`;
  const m = Math.floor(ms / 60_000);
  const s = Math.round((ms % 60_000) / 1000);
  return `${m} m ${String(s).padStart(2, '0')} s`;
}

/** Short local time ("14:05") for a message timestamp. */
export function formatTime(date: Date) {
  return date.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
}

/** Pretty-prints any value as JSON; falls back to String() for cyclic or exotic values. */
export function toJson(value: unknown) {
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value, null, 2) ?? String(value);
  } catch {
    return String(value);
  }
}
